<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import type {Schema} from '@/core/contracts'
import {can,projectId} from '@/core/session'
import {ApiError,identityEpoch,onIdentityChange} from '@/core/http'
import {formatTime} from '@/core/time'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import {readSceneVersion,readSceneTaskName} from './scene-editor-api'
import {scenePropertyConfig,scenePropertyTransformConfig,sceneCloudTransformConfig,sceneCloudOperationText,sceneTaskConfig,sceneDelayConfig,sceneNodeList,type SceneNode} from './scene-editor-draft'
import {writePreprocessJson,type ExactJson} from './preprocess-exact-json'
import {selectedTaskChoices} from './task-choices'
import type {SceneLogEntry} from './scene-debug-log-api'
const props=defineProps<{sceneId:string;entry:SceneLogEntry}>(),emit=defineEmits<{denied:[cause:ApiError]}>()
const nodes=ref<SceneNode[]>([]),names=ref(new Map<string,string>()),tasks=ref(new Map<string,string>()),error=ref('')
const readable=computed(()=>can('rule:manage')),deviceLinks=computed(()=>can('device:read')),taskLinks=computed(()=>can('task:read'))
let controller:AbortController|undefined,turn=0,alive=true
function reset(){turn++;controller?.abort();nodes.value=[];names.value=new Map();tasks.value=new Map();error.value=''}
function current(token:number,project:string,epoch:number){return alive&&token===turn&&project===projectId.value&&epoch===identityEpoch()&&readable.value}
async function load(){
 reset();if(!readable.value)return
 const token=turn,project=projectId.value,epoch=identityEpoch();controller=new AbortController();const signal=controller.signal
 try{
  const loaded=await readSceneVersion(project,props.sceneId,props.entry.versionId,signal);if(!current(token,project,epoch))return;nodes.value=sceneNodeList(loaded.actions)
  if(deviceLinks.value){try{const ids=[...new Set(props.entry.actions.flatMap(row=>{const node=nodes.value[row.ordinal],transform=node&&(sceneCloudTransformConfig(node)||scenePropertyTransformConfig(node));return [...(row.targetDeviceId?[row.targetDeviceId]:[]),...(transform?.operations.flatMap(op=>op.op==='set_ref'?[op.refDeviceId]:[])??[])]}))].slice(0,100);if(ids.length){const rows=await selectedTaskChoices(project,'devices',ids,signal);if(current(token,project,epoch)&&deviceLinks.value)names.value=new Map(rows.map(row=>[row.id,row.label]))}}catch{/* 名称不可读时保留真实UUID。 */}}
  const ids=taskLinks.value?[...new Set(props.entry.actions.flatMap(row=>{const node=nodes.value[row.ordinal];const task=node&&sceneTaskConfig(node as Schema<'SceneActionRequest'>);return task&&task.deviceId===row.targetDeviceId?[task.taskId]:[]}))].slice(0,20):[],resolved=new Map<string,string>()
  for(let offset=0;offset<ids.length;offset+=4){await Promise.all(ids.slice(offset,offset+4).map(async id=>{try{const value=await readSceneTaskName(project,id,signal);resolved.set(id,value.name)}catch{/* 原任务失效时不伪造名称。 */}}));if(!current(token,project,epoch))return}
  if(current(token,project,epoch)&&taskLinks.value)tasks.value=resolved
 }catch(cause){if(current(token,project,epoch)){error.value='原操作描述暂未读取，已记录结果保持显示。';if(cause instanceof ApiError&&[401,403].includes(cause.status))emit('denied',cause)}}
}
watch([projectId,()=>props.sceneId,()=>props.entry.executionId,()=>props.entry.versionId,readable,deviceLinks,taskLinks],()=>{void load()},{immediate:true})
const dispose=onIdentityChange(reset);onScopeDispose(()=>{alive=false;reset();dispose()})
const kinds:Record<string,{label:string;glyph:string}>={'scene-device-property-set-action':{label:'属性下发',glyph:String.fromCodePoint(0xf0552)},'scene-device-property-transform-action':{label:'属性下发',glyph:String.fromCodePoint(0xf0552)},'scene-device-cloud-update-action':{label:'属性更新',glyph:String.fromCodePoint(0xf0b7e)},'scene-device-cloud-transform-action':{label:'属性更新',glyph:String.fromCodePoint(0xf0b7e)},'scene-task-run-action':{label:'执行任务',glyph:String.fromCodePoint(0xf13c1)},'scene-delay-action':{label:'延迟等待',glyph:String.fromCodePoint(0xf051b)}}
const resultLabels={SUCCEEDED:'完成',FAILED:'失败',PENDING:'执行中',UNKNOWN:'结果未确认',SKIPPED:'跳过',TERMINATED:'终止',NOT_RUN:'已跳过'}
function summaryValue(value:ExactJson){if(typeof value==='string')return value;try{return writePreprocessJson(value,true)}catch{return writePreprocessJson(value)}}
const rows=computed(()=>props.entry.actions.map(action=>{
 const frozen=nodes.value[action.ordinal] as Schema<'SceneActionRequest'>|undefined,node=frozen?.nodeType===action.nodeType?frozen:undefined,property=node&&scenePropertyConfig(node),transform=node&&(sceneCloudTransformConfig(node)||scenePropertyTransformConfig(node)),task=node&&sceneTaskConfig(node),delay=node&&sceneDelayConfig(node)
 return {...action,delay:delay?`延迟 ${delay.durationSeconds%60===0?delay.durationSeconds/60+' 分钟':delay.durationSeconds+' 秒'}`:'',kind:kinds[action.nodeType]??{label:'操作',glyph:String.fromCodePoint(0xf0831)},properties:transform&&transform.deviceId===action.targetDeviceId?transform.operations.map(row=>sceneCloudOperationText(row,summaryValue,id=>names.value.get(id)||id)).join(', '):property&&property.deviceId===action.targetDeviceId?Object.entries(property.properties).map(([key,value])=>`${key} ${summaryValue(value)}`).join(', '):'',task:task&&task.deviceId===action.targetDeviceId?task.taskId:undefined}
}))
</script>
<template><div v-if="readable" class="scene-log-timeline"><p v-if="error" class="description-error">{{error}}</p><p v-if="!entry.coverageComplete" class="coverage-note">部分操作结果尚未确认。</p>
 <el-timeline v-if="rows.length" class="action-timeline"><el-timeline-item v-for="row in rows" :key="row.ordinal" :color="row.result==='SUCCEEDED'?'#67c23a':row.result==='FAILED'?'#f56c6c':row.result==='PENDING'||row.result==='TERMINATED'?'#e6a23c':'#409eff'"><template #dot><div class="timeline-dot" :class="row.result.toLowerCase()"><ReferenceIcon :glyph="row.kind.glyph"/></div></template><div class="timeline-content"><div class="timeline-header"><span class="header-type">{{row.kind.label}}</span><span class="header-time">{{row.completedAt||row.acceptedAt?formatTime(row.completedAt||row.acceptedAt):'时间未知'}}</span><span class="status-icon" :class="row.result.toLowerCase()"><ReferenceIcon :glyph="String.fromCodePoint(row.result==='SUCCEEDED'?0xf05e0:row.result==='FAILED'?0xf0028:0xf0026)"/>{{resultLabels[row.result]}}</span></div><div class="timeline-action-detail"><span v-if="row.delay" class="detail-item"><ReferenceIcon :glyph="String.fromCodePoint(0xf051b)"/>{{row.delay}}</span><span v-if="row.targetDeviceId" class="detail-item"><ReferenceIcon :glyph="String.fromCodePoint(0xf0697)"/><router-link v-if="deviceLinks" :to="`/devices/${row.targetDeviceId}`">{{names.get(row.targetDeviceId)||row.targetDeviceId}}</router-link><span v-else>{{row.targetDeviceId}}</span></span><span v-if="row.properties" class="detail-item"><ReferenceIcon :glyph="String.fromCodePoint(0xf0279)"/>{{row.properties}}</span><span v-if="row.task" class="detail-item"><ReferenceIcon :glyph="String.fromCodePoint(0xf00f0)"/><router-link v-if="taskLinks" :to="`/tasks/jobs/${row.task}`">{{tasks.get(row.task)||row.task}}</router-link><span v-else>{{row.task}}</span></span></div><div v-if="row.result==='FAILED'" class="timeline-error">操作失败，未记录详细原因。</div></div></el-timeline-item></el-timeline>
 <div v-else class="unexpanded-result"><strong>{{resultLabels[entry.result]}}</strong><span>{{entry.sourceStatus==='SKIPPED'?'已跳过':entry.sourceStatus==='TERMINATED'?'已终止':entry.result==='PENDING'?'已触发一次执行':entry.sourceStatus==='FAILED'?'执行失败，未记录具体节点原因。':'没有可确认的操作结果。'}}</span></div>
</div></template>
<style scoped>
.action-timeline{padding-left:8px;margin-top:12px}.timeline-dot{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#409eff;margin-left:-4px}.timeline-dot .reference-icon{font-size:16px;color:#fff}.timeline-dot.succeeded{background:#67c23a}.timeline-dot.failed{background:#f56c6c}.timeline-dot.pending,.timeline-dot.terminated{background:#e6a23c}.action-timeline :deep(.el-timeline-item__tail){left:10px}.action-timeline :deep(.el-timeline-item__content){padding-left:10px}.timeline-content{padding-top:2px}.timeline-header{display:flex;align-items:center;gap:8px;margin-bottom:4px}.header-type{font-weight:500;color:#333;font-size:14px}.header-time{color:#999;font-size:12px}.status-icon{display:flex;align-items:center;gap:4px;font-size:12px;color:#409eff;margin-left:auto;margin-right:20px}.status-icon .reference-icon{font-size:16px}.status-icon.succeeded{color:#67c23a}.status-icon.failed{color:#f56c6c}.status-icon.pending,.status-icon.terminated{color:#e6a23c}.timeline-action-detail{display:flex;flex-wrap:wrap;gap:12px;margin-top:4px}.detail-item{display:inline-flex;align-items:center;gap:4px;font-size:12px;color:#666;background:#f0f9ff;padding:2px 8px;border-radius:4px;overflow-wrap:anywhere}.detail-item .reference-icon{font-size:14px;color:#409eff}.detail-item a{color:inherit;text-decoration:none}.detail-item a:hover{color:#409eff}.timeline-error{display:flex;align-items:flex-start;gap:6px;margin-top:6px;padding:8px 10px;background:#fef0f0;border-radius:4px;font-size:12px;color:#f56c6c;line-height:1.4}.description-error,.coverage-note{font-size:12px;color:#909399;line-height:20px;margin:8px 0}.unexpanded-result{display:flex;gap:10px;margin:12px 0;color:#666;font-size:13px}.unexpanded-result strong{font-weight:500}
</style>
